# frozen_string_literal: true

module Authentication
  # Data needed to enroll an authenticator app: otpauth URI and its QR code.
  class TotpProvisioning
    ISSUER = "Servora"

    def initialize(user:, secret:)
      @user = user
      @secret = secret
    end

    def uri
      @user.otp_provisioning_uri(@user.email, issuer: ISSUER, otp_secret: @secret)
    end

    def formatted_secret
      @secret.scan(/.{1,4}/).join(" ")
    end

    # SVG markup generated by rqrcode from the URI. The output contains only a
    # <path> with numeric coordinates and fixed attributes (the URI is encoded
    # as modules, never emitted as text), so it is safe to render as HTML.
    def qr_svg
      svg = RQRCode::QRCode.new(uri).as_svg(
        use_path: true, viewbox: true, color: "1a1416", shape_rendering: "crispEdges", module_size: 4, standalone: true,
        svg_attributes: { role: "img", "aria-label": "QR code para configurar o aplicativo autenticador" }
      )
      svg.html_safe # rubocop:disable Rails/OutputSafety
    end
  end
end
